def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); st = list(feats.stratum); levs = sorted(set(st))
    S = np.ones((n, 1))
    if len(levs) > 1:
        S = np.column_stack([np.ones(n)] + [np.array([s == l for s in st], float) for l in levs[1:]])
    def ll(Z):
        b = np.zeros(Z.shape[1])
        for _ in range(30):
            eta = np.clip(Z @ b, -30, 30); mu = 1 / (1 + np.exp(-eta)); w = mu * (1 - mu) + 1e-9
            H = Z.T @ (Z * w[:, None]) + 1e-6 * np.eye(Z.shape[1])
            step = np.linalg.solve(H, Z.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(Z @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    R = np.corrcoef(X, rowvar=False)
    def base(sel): return np.column_stack([S] + [X[:, j] for j in sel])
    sel = []
    while len(sel) < MAX_DRIVERS:
        l0 = ll(base(sel)); best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            g = 2 * (ll(np.column_stack([base(sel), X[:, j]])) - l0)
            if best is None or g > best[0]: best = (g, j)
        if best is None: break
        alpha = 0.25 / p if not sel else 0.05 / p
        if stats.chi2.sf(best[0], 1) > alpha: break
        j = best[1]
        cl = [k for k in range(p) if abs(R[j, k]) >= 0.6 and k not in sel]
        if len(cl) > 1:
            lj = ll(np.column_stack([base(sel), X[:, j]])); cand = []
            for k in cl:
                lk = ll(np.column_stack([base(sel), X[:, k]]))
                if lk >= lj - 2:
                    cand.append((sum(R[k, m] ** 2 for m in cl), k))
            j = max(cand)[1]
        sel.append(j)
    changed = True
    while changed and sel:
        changed = False; lf = ll(base(sel))
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (lf - ll(base(rest))), 1) > 0.05 / p:
                sel = rest; changed = True; break
    prods = []; npair = p * (p + 1) / 2; cands = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b}); Z = base(mains); l0 = ll(Z)
            g = 2 * (ll(np.column_stack([Z, X[:, a] * X[:, b]])) - l0)
            if stats.chi2.sf(g, 1) < 0.002 / npair: cands.append((g, a, b))
    used = set()
    for g, a, b in sorted(cands, reverse=True):
        if len(prods) >= 2 or a in used or b in used: continue
        prods.append((a, b)); used |= {a, b}
    drv = [j for j in sel]
    for a, b in prods:
        for j in (a, b):
            if j not in drv: drv.append(j)
    drv = drv[:MAX_DRIVERS]
    cols = sorted(set(sel) | {j for ab in prods for j in ab})
    return Design(drivers=tuple(ids[j] for j in drv), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

